input.newString:
const asteroids = [];
// Power‑up circles (collect for score)
const powerUps = [];
const POWERUP_INTERVAL = 10000; // ms
let lastPowerUp = 0;
function spawnPowerUp() {
  const radius = 12;
  const x = Math.random() * (canvas.width - 2 * radius) + radius;
  const y = -radius;
  powerUps.push({ x, y, radius, speed: 1.5, collected: false });
}
function drawPowerUps() {
  powerUps.forEach(p => {
    const grad = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.radius);
    grad.addColorStop(0, '#ff0');
    grad.addColorStop(1, '#ff8800');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
    ctx.fill();
  });
}
function updatePowerUps(delta) {
  for (let i = powerUps.length - 1; i >= 0; i--) {
    const p = powerUps[i];
    p.y += p.speed;
    if (p.y - p.radius > canvas.height) powerUps.splice(i, 1);
    // check collection with ship
    const dx = p.x - ship.x;
    const dy = p.y - ship.y;
    const dist = Math.hypot(dx, dy);
    if (dist < p.radius + ship.radius) {
      // increase score
      score += 10;
      powerUps.splice(i, 1);
    }
  }
}

